/*
A = ||T||_P
                    where 
                    T: ℝ ^ 2: a sequence
                    P: ℝ ^ (2×2): a sequence
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>

struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    DT A;

    heartlib(
        const Eigen::Matrix<double, 2, 1> & T,
        const Eigen::Matrix<double, 2, 2> & P)
    {

        // A = ||T||_P
        A = sqrt((T).transpose()*P*(T));
    }
};

