outputs.matlab:
function output = heartlib(T, P)
% output = heartlib(T, P)
%
%    A = ||T||_P
%                        where 
%                        T: ℝ ^ 2: a sequence
%                        P: ℝ ^ (2×2): a sequence
    T = reshape(T,[],1);

    assert( numel(T) == 2 );
    assert( isequal(size(P), [2, 2]) );

    % A = ||T||_P

    A = sqrt((T)' * P * (T));
    output.A = A;
end

